1→// Yardımcı işlemler
2→
3→// Her öğe için fn'i SIRAYLA çağırır (bir çağrı bitmeden sonrakine geçmez); sonuçları aynı sırada döndürür.
4→async function siraylaIsle(ogeler, fn) {
5→  const sonuclar = [];
6→  for (const oge of ogeler) {
7→    sonuclar.push(await fn(oge));
8→  }
9→  return sonuclar;
10→}
11→
12→// fn'i (deneme numarasıyla: 0, 1, 2...) en fazla `deneme` kez çağırır; ilk başarılı sonucu döndürür.
13→// Hepsi başarısız olursa SON hatayı fırlatır.
14→async function tekrarDene(fn, deneme = 3) {
15→  let sonHata;
16→  for (let i = 0; i < deneme; i++) {
17→    try {
18→      return await fn(i);
19→    } catch (e) {
20→      sonHata = e;
21→    }
22→  }
23→  throw sonHata;
24→}
25→
26→// Her değerin kaç kez geçtiğini { deger: adet } nesnesi olarak döndürür.
27→function say(dizi) {
28→  const sayac = {};
29→  for (const x of dizi) {
30→    sayac[x] = (sayac[x] || 0) + 1;
31→  }
32→  return sayac;
33→}
34→
35→// Sayıların ortalaması; boş dizide 0.
36→function ortalama(dizi) {
37→  if (dizi.length === 0) return 0;
38→  return dizi.reduce((a, b) => a + b, 0) / dizi.length;
39→}
40→
41→// anahtarFn(oge) sonucuna göre gruplar: { anahtar: [ogeler...] }; öğelerin sırası korunur.
42→function grupla(dizi, anahtarFn) {
43→  return dizi.reduce((acc, oge) => {
44→    const k = anahtarFn(oge);
45→    (acc[k] = acc[k] || []).push(oge);
46→    return acc;
47→  }, {});
48→}
49→
50→module.exports = { siraylaIsle, tekrarDene, say, ortalama, grupla };

